WITH base AS (SELECT *, GREATEST(quantity, unit_price) AS greatest_quantity_unit_price, CEIL(unit_price) AS unit_price_whole FROM order_items WHERE product_id IS NULL), joined AS (SELECT s.id, s.order_id, s.product_id, s.greatest_quantity_unit_price, s.unit_price_whole, p.status FROM base s JOIN orders p ON s.order_id = p.id), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, status ORDER BY greatest_quantity_unit_price DESC, id) AS rank_in_group FROM joined) x WHERE rank_in_group = 1), with_windows AS (SELECT *, COUNT(greatest_quantity_unit_price) OVER (PARTITION BY status, order_id ORDER BY unit_price_whole, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_greatest_quantity_unit_price, SUM(greatest_quantity_unit_price) OVER (PARTITION BY status, order_id ORDER BY unit_price_whole, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_greatest_quantity_unit_price, AVG(greatest_quantity_unit_price) OVER (PARTITION BY status, order_id ORDER BY unit_price_whole, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_greatest_quantity_unit_price, MAX(greatest_quantity_unit_price) OVER (PARTITION BY status, order_id ORDER BY unit_price_whole, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_greatest_quantity_unit_price, SUM(greatest_quantity_unit_price) OVER (ORDER BY greatest_quantity_unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_greatest_quantity_unit_price FROM ranked WHERE unit_price_whole = 37), scored AS (SELECT id, order_id, product_id, greatest_quantity_unit_price, unit_price_whole, status, last7_count_greatest_quantity_unit_price, last7_avg_greatest_quantity_unit_price, last7_max_greatest_quantity_unit_price, cumulative_greatest_quantity_unit_price, SUM(unit_price_whole) OVER (PARTITION BY order_id ORDER BY last7_sum_greatest_quantity_unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_unit_price_whole, ROUND(last7_count_greatest_quantity_unit_price / SUM(last7_count_greatest_quantity_unit_price) OVER (PARTITION BY product_id), 4) AS last7_count_greatest_quantity_unit_price_share, ROW_NUMBER() OVER (PARTITION BY status ORDER BY last7_sum_greatest_quantity_unit_price DESC, id) AS seq_no FROM with_windows) SELECT o.status AS order_status, src.status AS order_item_status, COUNT(*) AS cnt, MIN(src.cumulative_unit_price_whole) AS min_cumulative_unit_price_whole, MAX(src.greatest_quantity_unit_price) AS max_greatest_quantity_unit_price FROM scored src JOIN orders o ON src.order_id = o.id GROUP BY GROUPING SETS ((o.status, src.status), (o.status), ()) ORDER BY order_status DESC;
